  function resolveOfficialBlank(blank) {
    const official = OFFICIAL_STANDARD_ANSWER_INDEX[blank.officialId];
    if (!official) throw new Error(`公式標準解答台帳にない正答ID: ${blank.officialId}`);
    return { ...blank, answerKey: official.key, answerText: official.text };
  }

  function multiBlankQuestion(metaData, set) {
    const blanks = set.blanks.map(resolveOfficialBlank);
    return {
      ...metaData,
      type: 'multi-blank',
      questionKind: 'knowledge',
      knowledgeType: 'official-multi-blank',
      prompt: set.prompt,
      diagram: set.diagram || '',
      answerGroups: set.answerGroups,
      blanks,
      answer: blanks.map(blank => `${blank.id}:${blank.answerKey}`).join('|'),
      answerText: blanks.map(blank => `〔${blank.id}〕${blank.answerText}`).join('／'),
      officialAnswerIds: blanks.map(blank => blank.officialId),
      source: { year:set.year, problem:set.problem, subquestion:set.subquestion, answerOrigin:'公式標準解答' },
      hint: '文章全体を読み、各空欄の前後関係を確認してから解答群の記号を選ぶ。',
      formula: `確認箇所：${set.year}年度 問題${set.problem} ${set.subquestion}（公式標準解答対応）`,
      clue: '一つの用語だけでなく、同じ文章内の空欄同士の関係から判断する。',
      steps: [
        { label:'3. 計算または説明', text:`🟦 ${set.explanation3}` },
        { label:'4. 間違いやすい点', text:`🟦 ${set.explanation4}` }
      ]
    };
  }

